#!/usr/bin/env bash
# =============================================================================
# HERCOSSNUX PQC IP Core - Layer 3B step 2: ML-DSA samplers
#
# Four samplers in one unit over the shared Keccak sponge:
#   "00" RejNTTPoly (ExpandA)  "01" RejBoundedPoly (ExpandS)
#   "10" ExpandMask            "11" SampleInBall
#
# THE REFILL THAT IS NOT A RESTART. The reference model, on running short of
# stream, squeezes a LONGER output and re-parses from the beginning. That
# reads like a restart but is not one: SHAKE is an XOF, so a longer squeeze is
# a prefix-extension of the shorter one and the accepted coefficients are
# identical. Verified against the oracle over 200 seeds BEFORE writing RTL,
# which removed the restart bookkeeping entirely. The sampler pulls bytes on
# demand from one continuous stream.
#
# TWO SURVIVING MUTATIONS, TWO DIAGNOSES. M2 (accepting z == q) was a real
# coverage gap: the condition arises with probability 2^-23, so across ~2048
# candidates it is expected 0.0002 times. Fixed with a synthetic boundary
# stream whose first candidate is exactly q, the same shape of fix as the
# Decaps byte-0 vectors. M7 (emit threshold 19 vs 20) was a NO-OP mutation:
# nbit only ever takes values 8, 12, 16, 20, 24 and is never 19, so no input
# could kill it; rewritten to corrupt the field mask instead.
#
# Adds new files only; nothing from ML-KEM or from the NTT-D step is touched.
# Installs into: $HOME/vhdl_repo/IP_Cores/PQC/
# Expected final line:
#   PQC L3B SAMPD PASS ntt=9 bnd=8 msk=8 ball=8 sig=b518e5241f86de0f
# =============================================================================
set -u
(
  set -e
  DEST="$HOME/vhdl_repo/IP_Cores/PQC"
  mkdir -p "$DEST/rtl" "$DEST/verif" "$DEST/doc"
  for f in rtl/ntt_d_tables_pkg.vhd rtl/ntt_d_unit.vhd; do
    if [ ! -f "$DEST/$f" ]; then
      echo "MISSING PREREQUISITE: $f"
      exit 1
    fi
  done
  base64 -d > "$DEST/rtl/sampler_d.vhd" << 'B64EOF'
