  chmod +x "$DEST/verif/mutate_sampd.sh"
  cd "$DEST/verif"
  rm -rf work-obj08.cf
  ghdl -a --std=08 ../rtl/ntt_d_tables_pkg.vhd ../rtl/poly_mem_d.vhd \
       ../rtl/ntt_d_unit.vhd ../rtl/sampler_d.vhd \
       tb_ntt_d.vhd tb_sampler_d.vhd

  echo "--- NTT-D datapath still bit-identical ---"
  ghdl -e --std=08 tb_ntt_d > /dev/null 2>&1
  ghdl -r --std=08 tb_ntt_d --stop-time=300ms 2>&1 \
    | grep "NTTD PASS" | sed 's/.*(report note): //'

  echo "--- ML-DSA samplers ---"
  ghdl -e --std=08 tb_sampler_d > /dev/null 2>&1
  ghdl -r --std=08 tb_sampler_d --stop-time=100ms 2>&1 \
    | grep "SAMPD PASS" | sed 's/.*(report note): //'
)
